          extra_headers: extra_headers,
          timeout: timeout
        )
      end
    end

    # Operations on inboxes events.
    class InboxesEvents < Base
      # Stream inbox events.
      #
      # BillionSend extension: a server-sent event stream of every inbox event of the team, named
      # like the webhook events (inbox.email.received, inbox.thread.created, email.received, …;
      # types narrows them), each carrying the webhook payload's data. Send the key as a Bearer
      # header; the stream stays open, and a client that reconnects with Last-Event-ID resumes
      # without losing events. Needs a team-wide key: a key held to one domain streams one inbox at
      # a time. An agent (an inbox-scoped key, or an MCP connection) never receives the events about
      # held mail (inbox.email.quarantined), replay included, and naming them in types is a 403. A
      # stream closes within a few seconds once its key is revoked, its person leaves the team or
      # its inbox is gone; it is also closed every ten minutes or so, and the client reconnects with
      # Last-Event-ID. Streams are capped per key and per team on each API process (429
      # too_many_streams).
      #
      # +GET /inboxes/events+
      #
      # @return [BillionSend::EventStream]
      def stream(
        types: nil,
        last_event_id: nil,
        max_reconnects: 5,
        extra_headers: nil,
        timeout: nil
      )
        @client.stream_events(
          "/inboxes/events",
          query: { "types" => types },
          last_event_id: last_event_id,
          max_reconnects: max_reconnects,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end

      # Stream one inbox's events.
      #
      # BillionSend extension: the event stream of one inbox, as GET /inboxes/events, ending when
      # the inbox is deleted or expires. An inbox-scoped key may stream its own inbox, without the
      # events about held mail.
      #
      # +GET /inboxes/{inbox_id}/events+
      #
      # @return [BillionSend::EventStream]
      def stream_inbox(
        inbox_id,
        types: nil,
        last_event_id: nil,
        max_reconnects: 5,
        extra_headers: nil,
        timeout: nil
      )
        @client.stream_events(
          "/inboxes/#{Client.encode_path(inbox_id)}/events",
          query: { "types" => types },
          last_event_id: last_event_id,
          max_reconnects: max_reconnects,
          extra_headers: extra_headers,
          timeout: timeout
        )
      end
    end

